// The only entry point pages use for the backend (enforced by dependency-cruiser).
// Hooks and types are generated by orval from contracts/openapi.json (ADR-0019); never
// hand-write API types or fetch calls here.
import type { AxiosRequestConfig, AxiosResponse } from 'axios'

export * from '@/lib/api/generated'

/** The selected demo user travels in X-Demo-User (a demo switcher, not authentication). */
export const userHeaders = (user: string) => ({ 'X-Demo-User': user })

/**
 * Options for a generated per-user query hook. The user is part of the query key: the
 * generated keys only contain the URL, so without it a cached response of one user (who may
 * read restricted papers) would be shown to another.
 */
export function asUser<T>(user: string, path: string) {
  const axios: AxiosRequestConfig = { headers: userHeaders(user) }
  return {
    axios,
    query: {
      queryKey: [path, user],
      select: (response: AxiosResponse<T>) => response.data,
      // While a new selection loads, keep showing the previous result (no blanking, focus
      // stays put), but never across users: another user's data must not flash on screen.
      placeholderData: (
        previous: AxiosResponse<T> | undefined,
        previousQuery: { queryKey: readonly unknown[] } | undefined,
      ) => (previousQuery?.queryKey[1] === user ? previous : undefined),
    },
  }
}
